{
 "kind": "sequence",
 "format": 1,
 "id": "seq_tonight_open",
 "name": "Tonight Show: cold open",
 "set": "set_tonight",
 "roles": {
  "a": {
   "mark": "e",
   "label": "Host"
  },
  "b": {
   "mark": "b",
   "label": "Sidekick"
  }
 },
 "wallText": "{show}",
 "wallSub": "Live from the Media Lot",
 "beats": [
  {
   "id": "b2",
   "shot": {
    "cam": "cam4",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "drift",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "Good evening. I'm {a.name}. We've got a good one tonight.",
     "Welcome to the show. Sit down, everybody, you paid for those seats."
    ]
   },
   "gfx": []
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam4",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "Our guest tonight is {guest}. Stick around."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{guest}",
     "sub": "Tonight's guest",
     "at": 0.4,
     "for": 4
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "a",
     "b"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "For the record, it's warm under these lights."
    ]
   },
   "gfx": []
  }
 ]
}
